def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal stripes: repeat the sequence of nonblank, constant-color rows.
    nonblank = [row[:] for row in grid if any(row)]
    if nonblank and all(len(set(row)) == 1 for row in nonblank):
        return [nonblank[i % len(nonblank)][:] for i in range(h)]

    marks = [(r + c, v) for r in range(h) for c in range(w)
             if (v := grid[r][c]) != 0]

    # Diagonal marks specify a repeating color sequence by r+c residue.
    for p in range(2, max(h, w) + 1):
        seq = {}
        if all((s % p not in seq or seq[s % p] == v)
               and not seq.setdefault(s % p, v) != v
               for s, v in marks):
            if len(seq) == p:
                return [[seq[(r + c) % p] for c in range(w)] for r in range(h)]

    # If no complete periodic sequence is determined, retain the input.
    return [row[:] for row in grid]
